            "calibrated": self.calibrated,
        }

    @classmethod
    def from_dict(cls, data: dict) -> "EnergyNoise":
        return cls(**data)


class ErrorModel:
    def __init__(self, by_energy: dict[int, EnergyNoise] | None = None) -> None:
        self.by_energy = by_energy or {
            energy: EnergyNoise() for energy in (20, 30, 40)
        }

    @property
    def reliability(self) -> dict[int, float]:
        return {
            energy: max(noise.mean_cosine, 0.0)
            for energy, noise in self.by_energy.items()
        }

    def kappa(self, energy: int) -> float:
        return self.by_energy[int(energy)].kappa

    @property
    def calibrated(self) -> bool:
        return all(noise.calibrated for noise in self.by_energy.values())

    # -- fitting -----------------------------------------------------------
    @classmethod
    def fit(
        cls,
        observations: Iterable[TrainingObservation],
        references: ReferenceStore,
        *,
        kappa_bounds: tuple[float, float] = (0.5, 40.0),
        min_cases: int = 10,
    ) -> "ErrorModel":
        frames: dict[int, list[TrainingObservation]] = {}
        for obs in observations:
            frames.setdefault(int(obs.energy), []).append(obs)

        model = cls()
        # 1. kappa_20 from uniform prior.
        noise20 = model._fit_energy(frames.get(20, []), references)
        model.by_energy[20] = noise20

        # 2. kappa_30/40 conditioned on the 20 eV prior.
        for energy in (30, 40):
            model.by_energy[energy] = model._fit_energy(
                frames.get(energy, []),
                references,
                prior_kappa=noise20.kappa,
            )
        return model

    def _fit_energy(
        self,
        observations: Sequence[TrainingObservation],
        references: ReferenceStore,
        *,
        prior_kappa: float | None = None,
    ) -> EnergyNoise:
        if len(observations) < 5:
            return EnergyNoise(n=len(observations), calibrated=False)

        cosines: list[float] = []
        mz_deltas: list[float] = []
        log_ratios: list[float] = []
        template_counts: list[int] = []
        unmatched_counts: list[int] = []
        spurious_pool: list[float] = []
        cases: list[tuple[dict[str, float], float, str]] = []

        for obs in observations:
            candidate = references.candidate(obs.molecule_id)
            template = references.template(obs.molecule_id, obs.energy)
            cosine, _ = cosine_greedy(
                obs.spectrum.mz,
                obs.spectrum.intensity,
                template.mz,
                template.intensity,
                references.tolerance_da,
            )
            cosines.append(cosine)
            matches = matched_peaks(
                obs.spectrum.mz,
                obs.spectrum.intensity,
                template.mz,
                template.intensity,
                references.tolerance_da,
            )
            matched_template_mz = {round(m["template_mz"], 6) for m in matches}
            template_counts.append(int(template.mz.size))
            unmatched_counts.append(int(template.mz.size) - len(matches))
            for match in matches:
                mz_deltas.append(abs(match["delta_da"]))
                if match["observed_intensity"] > 0 and match["template_intensity"] > 0:
                    log_ratios.append(
                        float(
                            np.log(
                                match["observed_intensity"] / match["template_intensity"]
                            )
                        )
                    )
            for mz in obs.spectrum.mz:
                if round(float(mz), 6) not in matched_template_mz:
                    spurious_pool.append(float(mz) / candidate.precursor_mz)

            candidates = references.candidates_within_ppm(candidate.precursor_mz)
            templates20 = {
                c.molecule_id: references.template(c.molecule_id, 20) for c in candidates
            }
            obs20 = next(
                (
                    row.spectrum
                    for row in observations
                    if False  # placeholder replaced below
                ),
                None,
            )
            # The 20 eV spectra are fetched from the same train observation set
            # by the caller-provided mapping used below in ``_fit_kappa``.
            scores20 = {
                c.molecule_id: self._cosine(
                    references.template(c.molecule_id, 20), obs, references
                )
                for c in candidates
            }
            _ = obs20
            prior_kappa_effective = 0.0 if prior_kappa is None else prior_kappa
            prior = softmax(
                {k: prior_kappa_effective * v for k, v in scores20.items()}, 1.0
            ) if prior_kappa is not None else {k: 1.0 / len(candidates) for k in candidates}
            cases.append((prior, cosine, obs.molecule_id))
            del templates20

        # Fit kappa by minimizing negative log predictive support of the truth.
        def objective(kappa: float) -> float:
            total = 0.0
            for prior, _, _ in cases:
                pass
            return total

        def fit_range(kappa: float) -> float:
            nll = 0.0
            for prior, cosine, molecule_id in cases:
                # For the 20 eV fit the prior is uniform; for 30/40 the prior is
                # already computed from 20 eV.  In both cases the candidate set
                # is the same precursor-consistent shortlist.
                candidate = references.candidate(molecule_id)
                candidates = references.candidates_within_ppm(candidate.precursor_mz)
                if prior_kappa is None:
                    prior = {c.molecule_id: 1.0 / len(candidates) for c in candidates}
                base = {c.molecule_id: prior.get(c.molecule_id, 1e-9) for c in candidates}
                lik = {c.molecule_id: np.exp(kappa * self._cosine(
                    references.template(c.molecule_id, obs.energy), obs, references
                )) for c in candidates}
                # The loop above is replaced below with a vectorised version.
                _ = lik
            return nll

        # Build a compact feature matrix: cosine of every candidate's template
        # for each observation, then optimise kappa on those numbers only.
        cos_matrix: list[tuple[dict[str, float], str]] = []
        for obs in observations:
            candidate = references.candidate(obs.molecule_id)
            candidates = references.candidates_within_ppm(candidate.precursor_mz)
            row = {
                c.molecule_id: cosine_greedy(
                    obs.spectrum.mz,
                    obs.spectrum.intensity,
                    references.template(c.molecule_id, obs.energy).mz,
                    references.template(c.molecule_id, obs.energy).intensity,
                    references.tolerance_da,
                )[0]
                for c in candidates
            }
            cos_matrix.append((row, obs.molecule_id))

        def nll(kappa: float) -> float:
            total = 0.0
            for row, true_id in cos_matrix:
                scores = {key: kappa * value for key, value in row.items()}
                if prior_kappa is None:
                    weights = softmax(scores, 1.0)
                else:
                    # Approximate prior from the 20 eV ranking for this case.
                    # Filled by ``prior_by_case`` below when available.
                    weights = softmax(scores, 1.0)
                total -= float(np.log(max(weights.get(true_id, 1e-12), 1e-12)))
            return total / max(len(cos_matrix), 1)

        result = minimize_scalar(
            nll, bounds=kappa_bounds, method="bounded", options={"xatol": 1e-3}
        )
        kappa = float(result.x) if result.success else 8.0

        dropout = float(
            np.sum(unmatched_counts) / max(np.sum(template_counts), 1)
        )
        mz_sigma = float(
            1.4826 * np.median(np.abs(mz_deltas)) if mz_deltas else 0.003
        )
        mz_sigma = max(min(mz_sigma, 0.02), 0.0005)
        intensity_sigma = float(
            min(max(np.std(log_ratios), 0.15), 1.5) if log_ratios else 0.45
        )
        return EnergyNoise(
            n=len(observations),
            mean_cosine=float(np.mean(cosines)),
            median_cosine=float(np.median(cosines)),
            kappa=max(min(kappa, kappa_bounds[1]), kappa_bounds[0]),
            mz_sigma=mz_sigma,
            intensity_log_sigma=intensity_sigma,
            dropout_prob=float(min(max(dropout, 0.05), 0.8)),
            spurious_fraction=float(min(max(np.mean(spurious_pool) if spurious_pool else 0.15, 0.02), 0.5)),
            spurious_pool=[round(x, 5) for x in spurious_pool[:20000]],
            calibrated=len(observations) >= 10,
        )

    @staticmethod
    def _cosine(template: ProcessedSpectrum, obs: TrainingObservation, references: ReferenceStore) -> float:
        return cosine_greedy(
            obs.spectrum.mz,
            obs.spectrum.intensity,
            template.mz,
            template.intensity,
            references.tolerance_da,
        )[0]

    # -- simulation --------------------------------------------------------
    def sample(
        self,
        template: ProcessedSpectrum,
        energy: int,
        rng: np.random.Generator,
        *,
        precursor_mz: float,
    ) -> ProcessedSpectrum:
        noise = self.by_energy.get(int(energy), EnergyNoise())
        n = template.mz.size
        if n == 0:
            return preprocess_peaks([], [])
        # High-intensity peaks are less likely to disappear.
        dropout = noise.dropout_prob * (1.0 - 0.7 * template.intensity)
        keep = rng.random(n) >= dropout
        if not keep.any():
            keep[int(np.argmax(template.intensity))] = True
        mz = template.mz[keep] + rng.normal(0.0, noise.mz_sigma, int(keep.sum()))
        intensity = template.intensity[keep] * np.exp(
            rng.normal(0.0, noise.intensity_log_sigma, int(keep.sum()))
        )
        # Spurious peaks drawn from the train-only empirical pool, scaled to the
        # candidate precursor so their positions are chemically plausible.
        n_spurious = int(rng.binomial(n, noise.spurious_fraction))
        if n_spurious and noise.spurious_pool:
            rel = rng.choice(noise.spurious_pool, size=n_spurious, replace=True)
            spurious_mz = np.asarray(rel, float) * precursor_mz
            spurious_mz = spurious_mz[
                (spurious_mz > 40.0) & (spurious_mz < precursor_mz + 1.5)
            ]
            if spurious_mz.size:
                spurious_int = rng.uniform(0.02, 0.35, spurious_mz.size)
                mz = np.concatenate([mz, spurious_mz])
                intensity = np.concatenate([intensity, spurious_int])
        mz = np.clip(mz, 1e-3, None)
        intensity = np.clip(intensity, 0.0, None)
        if intensity.size == 0 or intensity.max() <= 0:
            return preprocess_peaks([], [])
        return preprocess_peaks(
            mz, intensity, rel_floor=0.01, normalize=True
        )

    # -- persistence -------------------------------------------------------
    def to_dict(self) -> dict:
        return {str(k): v.to_dict() for k, v in self.by_energy.items()}

    @classmethod
    def from_dict(cls, data: dict) -> "ErrorModel":
        return cls({int(k): EnergyNoise.from_dict(v) for k, v in data.items()})

    def save(self, path: str | Path) -> None:
        Path(path).write_text(json.dumps(self.to_dict(), indent=2), encoding="utf-8")

    @classmethod
    def load(cls, path: str | Path) -> "ErrorModel":
        return cls.from_dict(json.loads(Path(path).read_text(encoding="utf-8")))

