    def __init__(self, energy: int):
        self.energy = int(energy)
        self.name = f"always_{energy}"

    def run(self, state, *, budget, rng=None):
        order = [self.energy] + [e for e in (30, 40) if e != self.energy]
        for energy in order[:budget]:
